const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',search:'M21 21l-6-6M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',remote:'M7 2h10v20H7zM10 6h4M10 10h.1M14 10h.1M10 14h.1M14 14h.1M10 18h.1M14 18h.1',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M3 21v-3c0-6 18-6 18 0v3Z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',chev:'m9 4 8 8-8 8',back:'m14 4-8 8 8 8',power:'M12 2v10M6 5a9 9 0 1 0 12 0',plus:'M12 3v18M3 12h18',minus:'M3 12h18',up:'m4 15 8-8 8 8',down:'m4 9 8 8 8-8',mute:'m3 3 18 18M4 10h3l5-5v8M12 17v3l-5-5H4z',return:'M9 4 3 10l6 6M3 10h12a6 6 0 0 1 0 12',menu:'M4 6h16M4 12h16M4 18h16',exit:'M13 3H3v18h10M10 12h11m-5-5 5 5-5 5',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1zM16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',refresh:'M20 5v6h-6M20 11a8 8 0 1 0-2 7',mic:'M9 3a3 3 0 0 1 6 0v9a3 3 0 0 1-6 0zM5 10v2a7 7 0 0 0 14 0v-2M12 19v4M8 23h8'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const img=(name,alt='',cls='')=>`<img class="${cls}" src="assets/${name}.webp" alt="${alt}" loading="lazy">`;
const names={movie:['탈주','인사이드 아웃 2','슈퍼배드 4'],drama:['굿파트너','백설공주에게 죽음을-Black Out','유어 아너'],show:['나 혼자 산다','그것이 알고 싶다','전지적 참견 시점'],free:['타겟','화란','마이 샤이 월드'],anime:['원피스 31기 (자막)',"귀멸의 칼날 : 도공 마을편",'나는 모든 것을 [패리]한다'],world:['하우스 오브 드래곤 시즌 2','투독장군반일한 : 장군의 반나절을…','하우스 오브 드래곤 시즌 1'],minion:['슈퍼배드 4','미니언즈 2','슈퍼배드 3'],actor:['하이재킹','1947 보스톤','비공식작전'],asia:['아맥종군 : 진격의 여자 아맥','내 이야기는 길어','어라운드쿼터'],grid:['라방','미씽 : 사라진 여자','화차','용의자 X','7년의 밤','악의 연대기','시간이탈자','비밀은 없다']};
const sections=[['영화 인기 TOP','movie'],['TV 드라마 인기 TOP','drama'],['TV 예능/교양 인기 TOP','show'],['#전국민 누구나 무료영화','free'],['애니 인기 TOP','anime'],['해외 시리즈 인기 TOP','world'],['#귀여운 악동! 미니언즈','minion'],['#이달의 배우, 하정우','actor'],['#지금 핫한 중드/일드','asia']];
const screens=[['home','홈'],['benefits','혜택+'],['remote','리모컨'],['more','더보기'],['category','카테고리'],['free','무료 콘텐츠']];let current='home',category='프라임슈퍼팩',filter='무료로 즐기는 반전 스릴러';let liked=new Set(JSON.parse(localStorage.getItem('genie-study-likes')||'[]'));
const poster=(name,i,rank=true)=>`<button class="poster" data-detail="${name}${i}" aria-label="${names[name][i]} 상세">${img(name+i,names[name][i])}${rank?`<span class="number">${i+1}</span>`:''}<small>${names[name][i]}</small></button>`;
const shelf=(title,name)=>`<section class="shelf"><div class="section-head"><h2>${title}</h2><button data-list="${name}" aria-label="${title} 전체 보기">${icon('chev')}</button></div><div class="posters">${names[name].map((_,i)=>poster(name,i)).join('')}</div></section>`;
const button=(name,label)=>`<button aria-label="${label}" data-action="${label}">${icon(name)}</button>`;
function brand(){return `<header class="brand"><span class="logo"><b>GENIE</b> TV</span><button class="kids-logo" data-action="키즈랜드">키즈랜드▸</button></header><div class="tabs"><button class="active" data-go="home">영화.TV.VOD</button><button data-go="category">프라임슈퍼팩</button></div>`}
function miniRemote(){return `<section class="mini-remote"><div class="section-head"><h2>리모컨</h2><button class="subtle" data-go="remote">크게보기</button></div><div class="controls"><div class="pair"><button class="round" data-action="전원" aria-label="전원">${icon('power')}</button><button class="round" data-action="뒤로" aria-label="뒤로">${icon('return')}</button></div><div class="pair"><button class="round" data-action="TV 홈" aria-label="TV 홈">${icon('home')}</button><button class="round" data-action="인기 채널"><small>인기<br>채널</small></button></div><div class="pill">${button('plus','볼륨 높이기')}${button('mute','음소거')}${button('minus','볼륨 낮추기')}</div><div class="pill">${button('up','다음 채널')}<button data-action="편성표"><small>편성표</small></button>${button('down','이전 채널')}</div></div></section>`}
const shortcuts=[['📺','Live 채널','live'],['🎉','이벤트','event'],['🎁','혜택+','benefits'],['🎟️','쿠폰함','coupon'],['📋','이용가이드','guide']];
function home(){return `${brand()}<div class="hero-track"><button class="hero" data-detail="drama2">${img('hero','유어 아너 — 자식을 위해 괴물이 되기로 한 두 아버지의 부성 본능 대치극')}</button><button class="hero" data-detail="movie0">${img('movie0','탈주')}</button><button class="hero" data-detail="movie1">${img('movie1','인사이드 아웃 2')}</button></div><div class="chips"><button class="chip" data-go="category">카테고리⌄</button><button class="chip" data-list="movie">최신영화</button><button class="chip" data-list="drama">TV/오리지널</button><button class="chip" data-go="free">무료</button></div>${miniRemote()}<button class="banner" data-action="이용가이드">${img('guide','지니 TV 모바일, 이렇게 사용하세요!')}</button><div class="shortcuts">${shortcuts.map(([e,t,a])=>`<button class="shortcut" ${a==='benefits'?'data-go="benefits"':`data-action="${t}"`}><span>${e}</span><small>${t}</small></button>`).join('')}</div>${sections.slice(0,3).map(x=>shelf(...x)).join('')}<section class="original">${img('original','스릴러부터 로맨스까지 지니 TV 오리지널')}<div class="posters">${poster('drama',2,false)}${poster('drama',1,false)}${poster('movie',0,false)}</div></section>${shelf(...sections[3])}<button class="banner kids-banner" data-action="키즈랜드">${img('kids','티니핑 월드에 초대합니다')}</button>${sections.slice(4).map(x=>shelf(...x)).join('')}<footer class="footer">고객센터 : (국번없이) 100　사업자 정보 ›<br>Copyrightⓒ kt corp. All rights reserved.<br><br><button data-top aria-label="맨 위로">↑</button></footer>`}
function benefits(){return `${brand()}<section class="benefits"><div class="handle"></div><div class="section-head"><h2>지니 TV 혜택+</h2><button class="subtle" data-action="쿠폰함">쿠폰함 ›</button></div><div class="benefit-title"><b>혜택<em>✚</em></b><p>지니 TV 고객이라면 받을 수 있는 혜택!</p></div>${Array.from({length:6},(_,i)=>`<button class="benefit-card" data-coupon="${i}" aria-label="${['호텔 7%','항공권 2%','투어 티켓 4%','그리팅 1만원','브랜디 4천원','몬스터짐 3천원'][i]} 쿠폰받기">${img('benefit'+i,'혜택 쿠폰 '+(i+1))}</button>`).join('')}</section>`}
function remote(){return `<div class="remote-header"><button data-action="전원" aria-label="전원">${icon('power')}</button><button data-connect>연결안됨⌄</button><button class="settings" data-action="리모컨 설정" aria-label="설정">${icon('settings')}</button></div><div class="connect-note"><span>지니 TV와 연결해주세요</span><button data-connect aria-label="다시 연결">${icon('refresh')}</button></div><div class="remote-panel"><div class="remote-tools">${[['return','뒤로'],['search','검색'],['home','TV 홈'],['menu','메뉴'],['exit','나가기']].map(x=>button(...x)).join('')}</div><div class="dpad-row"><div class="side-controls">${button('plus','볼륨 높이기')}${button('mute','음소거')}${button('minus','볼륨 낮추기')}</div><div class="dpad"><button class="up" data-action="위">▴</button><button class="left" data-action="왼쪽">◂</button><button class="ok" data-action="확인">확인</button><button class="right" data-action="오른쪽">▸</button><button class="down" data-action="아래">▾</button></div><div class="side-controls">${button('up','다음 채널')}<button data-action="편성표"><small>편성표</small></button>${button('down','이전 채널')}</div></div><div class="playback"><button data-action="선호 채널">선호<br>채널</button><div class="play-pill"><button data-action="되감기" style="color:#ee5252">◀</button><button data-action="재생 일시정지">▸Ⅱ</button><button data-action="빨리감기" style="color:#0093dc">▶</button></div><button data-action="인기 채널">인기<br>채널</button></div><div class="segment"><button data-keypad>키패드</button><button class="active" data-shortcut>바로가기</button></div><div class="vod"><h2>나의 VOD 콘텐츠</h2><div class="segment vod-tabs"><button class="active" data-vod="찜목록">찜목록</button><button data-vod="구매목록">구매목록</button><button data-vod="최근시청">최근시청</button></div><div id="vod-results"></div></div></div>`}
const tiles=[['📺','Live 채널'],['📺','편성표'],['🏠','키즈랜드'],['🎬','무료 영화'],['🎁','혜택+'],['🎟️','쿠폰함'],['📋','이용가이드'],['🟣','TV연결'],['🔔','알림'],['💳','월정액'],['genie','지니뮤직'],['Ⓜ','밀리의 서재']];
function more(){return `<section class="more"><div class="page-title"><h2>더보기</h2><button data-action="설정" aria-label="설정">${icon('settings')}</button></div><div class="more-grid">${tiles.map(([e,t])=>`<button class="tile" ${t==='혜택+'?'data-go="benefits"':t==='무료 영화'?'data-go="free"':`data-action="${t}"`}><span style="${e==='genie'?'color:#00a3ea;font-size:17px;font-weight:800':''}">${e}</span><small>${t}</small></button>`).join('')}</div><h3>기타</h3>${[['🎉','이벤트'],['⚑','공지사항'],['▣','FAQ'],['▤','1:1 문의'],['♧','제휴문의']].map(([e,t])=>`<button class="list-button" data-action="${t}"><span>${e}</span>${t}<span class="chev">${icon('chev')}</span></button>`).join('')}</section>`}
function categoryPage(){return `<section class="category"><div class="search"><label>${icon('search')}<input aria-label="콘텐츠 검색" placeholder="제목, 출연, 감독 검색" id="search-input"></label><button data-action="음성 검색" aria-label="음성 검색">${icon('mic')}</button></div><h3>월정액관</h3><div class="subscriptions">${[['#ae9871','프라임<br>슈퍼팩'],['#e5212c','프라임<br>무비팩'],['#aa049f','프라임<br>무비초이스'],['#272727','CJ ENM'],['#231466','KBS']].map(([c,t])=>`<button class="subscription" style="background:${c}" data-action="월정액관">${t}</button>`).join('')}</div><h3>전체</h3><div class="category-body"><div class="category-menu">${['프라임슈퍼팩','영화','TV/오리지널','해외 시리즈','애니/게임','무료','다큐/스포츠','키즈랜드'].map(t=>`<button class="${category===t?'active':''}" data-cat="${t}">${t}</button>`).join('')}</div><div class="category-content">${img('super','프라임슈퍼팩')}<div id="category-items">${categoryItems()}</div></div></div></section>`}
function categoryItems(){let items=category==='프라임슈퍼팩'?['슈퍼 PICK!','한국영화','외국영화','오리지널/TV','해외 시리즈','애니메이션','다큐멘터리·음악']:category==='무료'?['무료로 즐기는 반전 스릴러','액션/SF','드라마']:['인기 TOP','최신 콘텐츠','추천 콘텐츠'];return items.map(t=>`<button data-list="${category==='애니/게임'?'anime':category==='TV/오리지널'?'drama':'movie'}">${t}${icon('chev')}</button>`).join('')}
function freePage(){return `<div class="free-head"><button data-go="more" aria-label="뒤로">${icon('back')}</button><strong>무료</strong></div><div class="free-tabs">${['무료로 즐기는 반전 스릴러','액션/SF','드라마'].map(t=>`<button class="${filter===t?'active':''}" data-filter="${t}">${t}</button>`).join('')}</div><div class="sort"><button id="sort">최신순 ▼</button></div><div class="free-grid">${names.grid.map((_,i)=>poster('grid',i,false)).join('')}</div>`}
function render(name){current=name;document.querySelector('#screen').innerHTML=({home,benefits,remote,more,category:categoryPage,free:freePage}[name]||home)();document.querySelector('#screen-nav').innerHTML=screens.map(([id,t],i)=>`<button data-go="${id}" class="${id===name?'active':''}">${String(i+1).padStart(2,'0')}　${t}</button>`).join('');document.querySelector('#bottom').innerHTML=[['home','홈','home'],['category','카테고리','search'],['remote','리모컨','remote'],['my','마이','user'],['more','더보기','grid']].map(([id,t,ic])=>`<button ${id==='my'?'data-my':`data-go="${id}"`} class="${id===name||(name==='free'&&id==='more')?'active':''}">${icon(ic)}<small>${t}</small></button>`).join('');window.scrollTo(0,0);location.hash=name;}
function toast(s){let e=document.querySelector('#toast');e.textContent=s;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),2600)}
function modal(html){document.querySelector('#modal-content').innerHTML=html;document.querySelector('#modal').hidden=false}
function detail(key){let m=key.match(/(.*?)(\d+)$/);let title=names[m[1]][+m[2]];modal(`${img(key,title)}<h2>${title}</h2><p>원본 화면을 바탕으로 구성한 디자인 시연입니다. 실제 영상 재생·구매는 제공하지 않습니다.</p><button class="primary" data-like="${key}">${liked.has(key)?'♥ 찜 해제':'♡ 찜하기'}</button>`)}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.go){render(b.dataset.go);return}if(b.dataset.detail){detail(b.dataset.detail);return}if(b.dataset.list){let n=b.dataset.list;modal(`<h2>${sections.find(x=>x[1]===n)?.[0]||'콘텐츠'}</h2><div class="posters">${names[n].map((_,i)=>poster(n,i,false)).join('')}</div>`);return}if(b.dataset.like){let k=b.dataset.like;liked.has(k)?liked.delete(k):liked.add(k);localStorage.setItem('genie-study-likes',JSON.stringify([...liked]));b.textContent=liked.has(k)?'♥ 찜 해제':'♡ 찜하기';return}if(b.hasAttribute('data-connect')){modal('<h2>TV 연결</h2><p>현재는 디자인 프로토타입으로, 실제 TV를 검색하거나 연결하지 않습니다.</p><button class="primary dismiss-action">확인</button>');return}if(b.dataset.cat){category=b.dataset.cat;if(category==='무료'){render('free');return}render('category');return}if(b.dataset.filter){filter=b.dataset.filter;render('free');let grid=document.querySelector('.free-grid');if(filter!=='무료로 즐기는 반전 스릴러')grid.innerHTML=names[filter==='드라마'?'drama':'movie'].map((_,i)=>poster(filter==='드라마'?'drama':'movie',i,false)).join('');return}if(b.id==='sort'){let grid=document.querySelector('.free-grid');[...grid.children].reverse().forEach(x=>grid.appendChild(x));b.textContent=b.textContent.includes('최신')?'제목순 ▼':'최신순 ▼';return}if(b.hasAttribute('data-keypad')){modal(`<h2>키패드</h2><p id="digits">채널 번호를 입력하세요</p><div class="keypad">${['1','2','3','4','5','6','7','8','9','⌫','0','확인'].map(n=>`<button data-digit="${n}">${n}</button>`).join('')}</div>`);return}if(b.dataset.digit){let d=document.querySelector('#digits');if(b.dataset.digit==='확인'){toast('디자인 시연 · 실제 채널은 변경되지 않습니다');return}d.textContent=(d.textContent.includes('채널')?'':d.textContent);d.textContent=b.dataset.digit==='⌫'?d.textContent.slice(0,-1):d.textContent+b.dataset.digit;return}if(b.dataset.vod){document.querySelectorAll('.vod-tabs button').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('#vod-results').innerHTML=b.dataset.vod==='찜목록'&&liked.size?`<div class="posters" style="padding:20px 0">${[...liked].map(k=>{let m=k.match(/(.*?)(\d+)$/);return poster(m[1],+m[2],false)}).join('')}</div>`:`<div class="empty">${b.dataset.vod}이 없습니다.</div>`;return}if(b.dataset.coupon!==undefined){toast('쿠폰받기 UI 시연 · 실제 쿠폰은 발급되지 않습니다');return}if(b.hasAttribute('data-my')){modal('<h2>마이</h2><p>제공된 레퍼런스에 마이 화면이 없어 재현 범위에서 제외했습니다.</p><button class="primary dismiss-action">확인</button>');return}if(b.hasAttribute('data-top')){window.scrollTo({top:0,behavior:'smooth'});return}if(b.classList.contains('close'))document.querySelector('#review').hidden=true;if(b.classList.contains('dismiss')||b.classList.contains('dismiss-action'))document.querySelector('#modal').hidden=true;if(b.dataset.action)toast(`${b.dataset.action} · 디자인 시연 (실제 서비스 미연결)`);if(b.hasAttribute('data-shortcut'))toast('바로가기 모드입니다');});
document.querySelector('#modal').addEventListener('click',e=>{if(e.target.id==='modal')e.currentTarget.hidden=true});document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('#modal').hidden=true;document.querySelector('#review').hidden=true}if(e.key==='Enter'&&e.target.id==='search-input'){const term=e.target.value.trim();const result=Object.entries(names).flatMap(([n,list])=>list.map((t,i)=>({n,i,t}))).filter(x=>x.t.includes(term));modal(`<h2>검색 결과</h2><p>${term?'입력한 검색어와 일치하는 시연 콘텐츠':'전체 시연 콘텐츠'}</p><div class="free-grid">${result.map(x=>poster(x.n,x.i,false)).join('')||'검색 결과가 없습니다.'}</div>`)}});
document.querySelector('#compare').onclick=()=>{document.querySelector('#review-content').innerHTML=`<h2 style="text-align:center">원본 · ${screens.find(x=>x[0]===current)[1]}</h2><p style="text-align:center;color:#888">GDWEB 등록 이미지 / 2024.09.05</p><img class="ref-image" src="assets/ref-${current}.webp" alt="원본 화면">`;document.querySelector('#review').hidden=false};
document.querySelector('#tokens').onclick=()=>{document.querySelector('#review-content').innerHTML=`<article class="tokens-board"><span class="eyebrow">REUSABLE FOUNDATION</span><h1>GENIE TV 디자인 시스템</h1><p>레퍼런스 화면에서 관찰·추정한 재현용 토큰입니다. 공식 디자인 원본 수치는 아닙니다.</p><div class="swatches">${[['Background','#111111'],['Surface','#1b1b1b'],['Raised','#272727'],['Control','#303030'],['Text','#f5f5f5'],['Muted','#888888'],['Accent','#8050ff']].map(([t,c])=>`<div class="swatch"><span style="background:${c}"></span>${t}<br><small>${c}</small></div>`).join('')}</div><table><tr><th>항목</th><th>재현 기준</th></tr><tr><td>기준 화면</td><td>375px 모바일 / 본문 좌우 16px</td></tr><tr><td>타이포그래피</td><td>Noto Sans KR 대체 적용 · 12 / 14 / 16 / 20 / 23px</td></tr><tr><td>카드</td><td>포스터 110 × 158 · radius 10px / 히어로 333 × 399 · radius 22px</td></tr><tr><td>조작</td><td>원형 버튼 / 세로 캡슐 / 원형 D-pad / 세그먼트</td></tr><tr><td>정보 구조</td><td>상단 브랜드·탭 → 히어로 → 필터 → 리모컨 → 가로 선반 → 하단 5탭</td></tr><tr><td>전환</td><td>탭 전환, 가로 스크롤, 혜택 페이지, 상세 바텀시트</td></tr></table><h2>컴포넌트</h2><div class="chips"><button class="chip">카테고리⌄</button><button class="chip active">선택됨</button></div>${miniRemote()}<p>원본 확인 범위: 홈 · 혜택 · 리모컨 · 더보기 · 카테고리 · 무료 콘텐츠. 상세·연결·검색 결과 동작은 시연용 구성입니다.</p><p>차량용 변환 시 이 토큰은 출발점으로 활용하며, Pleos 앱 창 크기·가독성·주행 제한은 별도로 적용해야 합니다.</p></article>`;document.querySelector('#review').hidden=false};
window.addEventListener('hashchange',()=>{let n=location.hash.slice(1);if(screens.some(x=>x[0]===n)&&n!==current)render(n)});render(screens.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'home');
